JS (same embed) turning each title into a link to the real blog tag page:
<script>(function(){if(location.pathname.replace(/\/$/,'')!=='/tags')return;function go(){document.querySelectorAll('#comp-lpko32x32 [id^="comp-lpko32x44__"]').forEach(function(it){var s=it.querySelector('[id^="comp-lpko32x71__"]'),h=it.querySelector('[id^="comp-lpko32x57__"] h2');if(!s||!h||h.querySelector('a'))return;var slug=s.textContent.trim();if(!/^[a-z0-9-]+$/.test(slug))return;var a=document.createElement('a');a.href='/gatorbait-media-blogs/tags/'+slug;a.textContent=h.textContent.trim();h.textContent='';h.appendChild(a);});}var t;function later(){clearTimeout(t);t=setTimeout(go,150);}document.addEventListener('DOMContentLoaded',go);window.addEventListener('load',go);new MutationObserver(later).observe(document,{childList:true,subtree:true});})();</script>

